import {drawProjectile} from './projectile-effects.mjs';
import {MATERIALS} from './catalog.mjs';
import {camera,ARENA_BOUNDS} from './view.mjs';
const TAU=Math.PI*2;
function ellipse(c,x,y,rx,ry,color,stroke){c.beginPath();c.ellipse(x,y,rx,ry,0,0,TAU);c.fillStyle=color;c.fill();if(stroke){c.strokeStyle=stroke;c.lineWidth=2;c.stroke()}}
function polygon(c,pts,color,stroke){c.beginPath();pts.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.closePath();c.fillStyle=color;c.fill();if(stroke){c.strokeStyle=stroke;c.lineWidth=2;c.stroke()}}
function bottle(c,x,y,id,t){let col=MATERIALS[id].color;c.save();c.translate(x,y+Math.sin(t*3+x)*2);ellipse(c,0,14,12,4,'#091f1a55');c.fillStyle='#203c34';c.fillRect(-7,-11,14,22);c.strokeStyle=col;c.lineWidth=1.4;c.strokeRect(-7,-11,14,22);c.fillStyle=col;c.fillRect(-5,-3,10,12);c.fillStyle='#bed2bc';c.fillRect(-5,-15,10,4);c.restore()}
function diamond(c,d,t){c.save();c.translate(d.x,d.y+Math.sin(t*3+d.x)*2);ellipse(c,0,10,10,3,'#091f1a55');polygon(c,[[-10,-3],[-5,-10],[5,-10],[10,-3],[0,10]],'#efffe3','#b9d8a4');polygon(c,[[-10,-3],[0,-3],[0,10]],'#c2e8cc');polygon(c,[[0,-3],[5,-10],[10,-3],[0,10]],'#fff3b8');polygon(c,[[-5,-10],[0,-3],[5,-10]],'#ffffff');if(d.value>1){c.font='bold 11px monospace';c.textAlign='center';c.lineWidth=3;c.strokeStyle='#18392d';c.strokeText(String(d.value),0,24);c.fillStyle='#f4f5ce';c.fillText(String(d.value),0,24)}c.restore()}
function acidAura(c,e,t){c.save();c.translate(e.x,e.y);const g=c.createRadialGradient(0,0,e.r,0,0,90);g.addColorStop(0,'#76d8af18');g.addColorStop(.8,'#62d3a013');g.addColorStop(1,'#62d3a000');ellipse(c,0,0,90,90,g);c.strokeStyle='#7ce4b32b';c.lineWidth=1;c.setLineDash([3,9]);c.beginPath();c.arc(0,0,86+Math.sin(t*2)*3,0,TAU);c.stroke();c.restore()}
function enemy(c,e,t){
 c.save();c.translate(e.x,e.y);const r=e.r,a=t*2+(e.id||0),flash=e.flash>0;ellipse(c,0,r*.75,r+4,6,'#071c1755');
 if(e.type===1){
  c.save();c.rotate(Math.sin(a)*.18);for(let i=0;i<5;i++){let q=i*TAU/5;polygon(c,[[Math.cos(q)*r*.35,Math.sin(q)*r*.35],[Math.cos(q+.2)*r*1.5,Math.sin(q+.2)*r*1.5],[Math.cos(q+.65)*r*.65,Math.sin(q+.65)*r*.65]],flash?'#fff1d4':'#d49a64','#654b39')}polygon(c,[[-r,-r*.25],[-r*.3,-r],[r*.8,-r*.6],[r,r*.35],[0,r]],flash?'#fff3d7':'#ad794f','#ebc08b');c.restore();ellipse(c,-4,-2,2,3,'#fff4c7');ellipse(c,4,-2,2,3,'#fff4c7');
 }else if(e.type===2){
  for(let i=0;i<6;i++){const q=i*TAU/6;polygon(c,[[Math.cos(q)*r*.5,Math.sin(q)*r*.5],[Math.cos(q+.2)*r*1.25,Math.sin(q+.2)*r*1.25],[Math.cos(q+.55)*r*.7,Math.sin(q+.55)*r*.7]],'#82679e','#bea2d6')}
  polygon(c,[[-r,-r*.35],[-r*.5,-r],[r*.55,-r],[r,r*.2],[r*.45,r],[-r*.65,r*.8]],flash?'#f3e8ff':'#70578d','#c3a7e0');polygon(c,[[-r*.5,-r*.8],[0,-r*.2],[r*.5,-r*.8],[r*.7,r*.25],[0,r*.8],[-r*.75,r*.4]],'#9271ad','#b89bcc');if(e.hp<=e.maxHp/2){c.strokeStyle='#2a2244';c.lineWidth=3;c.beginPath();c.moveTo(0,-r);c.lineTo(-5,-5);c.lineTo(5,3);c.lineTo(-3,r);c.moveTo(5,3);c.lineTo(r,9);c.stroke()}ellipse(c,-7,-1,3,3,'#e7efb8');ellipse(c,7,-1,3,3,'#e7efb8');
 }else if(e.type===3){
  for(let i=0;i<(e.child?3:6);i++){const q=i*TAU/(e.child?3:6)+a*.12,x=Math.cos(q)*r*.55,y=Math.sin(q)*r*.45;ellipse(c,x,y,r*.58,r*.62,flash?'#f3f5d7':i%2?'#b3a5ce':'#8cbd98','#477a66');ellipse(c,x-r*.13,y-r*.18,r*.13,r*.18,'#e8f3da88')}ellipse(c,-r*.2,-1,2.5,3,'#253e39');ellipse(c,r*.2,-1,2.5,3,'#253e39');
 }else if(e.type===4){
  const phase=e.phase||1,col=phase===3?'#ffb071':phase===2?'#d1a2ed':'#9ee6c6';for(let i=0;i<4;i++){c.save();c.rotate(i*TAU/4+.3);c.fillStyle='#60776c';c.fillRect(r*.5,-7,r*.85,14);ellipse(c,r*1.25,0,9,11,'#354e46',col);c.restore()}polygon(c,[[-r*.8,-r*.65],[-r*.4,-r],[r*.5,-r],[r*.85,-r*.5],[r*.85,r*.65],[r*.4,r],[-r*.5,r],[-r*.85,r*.5]],flash?'#f4efd8':'#536b63','#9ab5a6');ellipse(c,0,0,r*.62,r*.72,'#213f39',col);ellipse(c,0,0,r*.42,r*.51,col);for(let i=0;i<phase+1;i++){let q=a+i*TAU/(phase+1);ellipse(c,Math.cos(q)*r*.28,Math.sin(q)*r*.34,5,7,'#ffffff99')}c.fillStyle='#b8d2be';c.fillRect(-r*.55,-r*.95,r*1.1,7);for(let i=0;i<3;i++){c.fillStyle=i<phase?col:'#263c34';c.fillRect(-15+i*12,r*.72,7,5)}
 }else{
  for(let i=0;i<5;i++){const q=i*TAU/5;ellipse(c,Math.cos(q)*r*.6,Math.sin(q)*r*.55,r*.63,r*.62,flash?'#eef4cf':'#65b5a0','#3f8373')}ellipse(c,0,0,r*.84,r*.78,flash?'#eef4cf':'#79c6ac');for(let i=0;i<3;i++)ellipse(c,Math.sin(a+i*2)*r*.7,-r-5-i*7,3+i,3+i,'#83d9bd55');ellipse(c,-r*.25,-2,3,4,'#203e37');ellipse(c,r*.25,-2,3,4,'#203e37');
 }
 if(e.burn>0){
  const glow=c.createRadialGradient(0,0,r*.3,0,0,r*1.9);glow.addColorStop(0,'#d5f3ff55');glow.addColorStop(.5,'#739dff44');glow.addColorStop(1,'#6593ff00');ellipse(c,0,0,r*1.9,r*1.9,glow);
  for(let i=0;i<5;i++){const x=(i-2)*r*.36,h=r*.9+14+Math.sin(t*14+i*2)*7,bend=Math.sin(t*11+i)*8;c.beginPath();c.moveTo(x-6,10);c.bezierCurveTo(x-10,-h*.3,x+7,-h*.65,x+bend,-h);c.bezierCurveTo(x+4,-h*.45,x+10,1,x+6,10);c.closePath();c.fillStyle='#789dffbb';c.fill();c.beginPath();c.moveTo(x-3,9);c.quadraticCurveTo(x+4,-h*.3,x+bend*.5,-h*.75);c.quadraticCurveTo(x+7,-h*.15,x+3,9);c.fillStyle='#e8f7ffee';c.fill()}
  c.font='bold 9px sans-serif';c.textAlign='center';c.fillStyle='#ffdfad';c.strokeStyle='#24392c';c.lineWidth=3;c.strokeText('灼烧',0,-r-25);c.fillText('灼烧',0,-r-25);c.fillStyle='#142c24';c.fillRect(-15,-r-21,30,3);c.fillStyle='#9dc8ff';c.fillRect(-15,-r-21,30*Math.min(1,e.burn/2.5),3);
 }c.restore()
}
function hazard(c,h,t){
 c.save();c.translate(h.x,h.y);const warning=h.elapsed<h.warning,pulse=.65+Math.sin(t*12)*.15;
 if(h.type==='ring'){
  const radius=warning?80:Math.max(0,(h.elapsed-h.warning)*h.speed),gap=h.gapAngle||0,half=h.gapHalfAngle??.55;
  // Only the dangerous arc is red; the open green gate remains traversable.
  c.lineWidth=warning?3:(h.width||18);c.strokeStyle=warning?'#f2ba69aa':'#f48c6cbb';if(warning)c.setLineDash([8,6]);c.beginPath();c.arc(0,0,radius,gap+half,gap+TAU-half);c.stroke();c.setLineDash([]);
  if(!warning){c.lineWidth=2;c.strokeStyle='#ffe3b6';c.beginPath();c.arc(0,0,radius,gap+half,gap+TAU-half);c.stroke()}
  c.lineWidth=3;c.strokeStyle='#95f2ba';c.beginPath();c.arc(0,0,radius,gap-half,gap+half);c.stroke();for(const a of [gap-half,gap+half]){c.beginPath();c.moveTo(Math.cos(a)*(radius-12),Math.sin(a)*(radius-12));c.lineTo(Math.cos(a)*(radius+12),Math.sin(a)*(radius+12));c.stroke()}
  if(warning){const x=Math.cos(gap)*radius,y=Math.sin(gap)*radius;c.font='bold 12px sans-serif';c.textAlign='center';c.fillStyle='#baffd0';c.fillText('缺口',x,y-15)}
 }else if(h.type==='zone'){
  const radius=h.radius||65;ellipse(c,0,0,radius,radius,warning?'#e6ac4324':'#f5644b44');c.strokeStyle=warning?'#efbd70':'#ff9278';c.lineWidth=warning?2:4;c.setLineDash(warning?[7,5]:[]);c.beginPath();c.arc(0,0,radius,0,TAU);c.stroke();c.setLineDash([]);
  if(warning){c.strokeStyle='#f6cc83';c.lineWidth=2;for(let i=0;i<4;i++){c.save();c.rotate(i*TAU/4);c.beginPath();c.moveTo(radius-12,0);c.lineTo(radius+7,0);c.stroke();c.restore()}const progress=Math.min(1,h.elapsed/Math.max(.01,h.warning));c.lineWidth=4;c.beginPath();c.arc(0,0,radius-7,-Math.PI/2,-Math.PI/2+TAU*progress);c.stroke();c.font='bold 22px sans-serif';c.textAlign='center';c.fillStyle='#f7ce89';c.fillText('!',0,8)}else{c.globalAlpha=pulse;for(let i=0;i<8;i++){const a=i*TAU/8+t*2;polygon(c,[[Math.cos(a)*radius*.2,Math.sin(a)*radius*.2],[Math.cos(a+.12)*radius*.9,Math.sin(a+.12)*radius*.9],[Math.cos(a+.25)*radius*.4,Math.sin(a+.25)*radius*.4]],'#ffc385')}ellipse(c,0,0,12,12,'#fff0c1')}
 }
 c.restore()
}
function bossBar(c,enemies,width){const boss=enemies.find(e=>e.type===4&&e.hp>0);if(!boss)return;c.save();const w=Math.min(360,width-40),x=(width-w)/2;c.fillStyle='#132b25e8';c.fillRect(x-8,12,w+16,43);c.font='bold 12px sans-serif';c.textAlign='center';c.fillStyle='#e4efd6';c.fillText('失控反应釜 · '+(boss.phase===3?'阶段 3 · 过载':'阶段 '+(boss.phase||1)),width/2,29);c.fillStyle='#304d40';c.fillRect(x,37,w,8);c.fillStyle=boss.phase===3?'#f5ad76':'#c6a6df';c.fillRect(x,37,w*Math.max(0,Math.min(1,boss.hp/boss.maxHp)),8);c.restore()}
function player(c,x,y,angle,gun,t,inv){c.save();c.translate(x,y);if(inv>0&&Math.floor(t*16)%2===0)c.globalAlpha=.45;ellipse(c,0,22,24,8,'#081d17aa');let step=Math.sin(t*11)*2;c.fillStyle='#6c8a7f';c.fillRect(-13,12+step,10,12);c.fillRect(4,12-step,10,12);ellipse(c,0,1,18,21,'#bdccc1','#324f43');c.save();c.rotate(angle);c.fillStyle=gun.type==='water'?'#77d9f5':gun.type==='flame'?'#b8c6ff':'#bed4a8';c.fillRect(10,1,30,10);c.fillStyle='#4f6d60';c.fillRect(33,-1,10,14);c.fillStyle='#d6e0cf';c.fillRect(17,3,14,3);ellipse(c,13,13,7,6,'#a3bdb1','#365548');c.restore();ellipse(c,0,-10,19,18,'#c6d2c9','#365549');ellipse(c,0,-11,14,10,'#2d524b','#779c8d');c.strokeStyle='#b4dfc1';c.lineWidth=2;c.beginPath();c.moveTo(-8,-14);c.lineTo(0,-14);c.stroke();ellipse(c,-9,-8,3,5,'#72938a');ellipse(c,9,-8,3,5,'#72938a');ellipse(c,0,1,5,4,'#7b9d8c','#365549');c.restore()}
function chamber(c,t){c.fillStyle='#21372f';c.fillRect(0,0,1200,800);let grad=c.createRadialGradient(600,400,50,600,400,650);grad.addColorStop(0,'#34513e77');grad.addColorStop(1,'#0e211b66');c.fillStyle=grad;c.fillRect(0,0,1200,800);c.strokeStyle='#71916a13';c.lineWidth=1;for(let x=0;x<=1200;x+=50){c.beginPath();c.moveTo(x,0);c.lineTo(x,800);c.stroke()}for(let y=0;y<=800;y+=50){c.beginPath();c.moveTo(0,y);c.lineTo(1200,y);c.stroke()}c.strokeStyle='#a0c68b99';c.lineWidth=3;c.strokeRect(22,22,1156,756);c.setLineDash([5,9]);c.strokeStyle='#a9c48b1f';c.beginPath();c.arc(600,400,145,0,TAU);c.stroke();c.setLineDash([]);for(let [x,y,r]of [[72,85,.1],[1100,720,2.2],[1090,82,.4],[80,715,2]]){c.save();c.translate(x,y);c.rotate(r);c.fillStyle='#304a38';c.fillRect(-25,-15,50,30);c.strokeStyle='#678464';c.lineWidth=1;c.strokeRect(-25,-15,50,30);c.fillStyle='#96b68a';c.fillRect(-18,-10,4,20);c.fillStyle='#1b3025';c.fillRect(-8,-10,26,20);c.restore()}c.font='10px monospace';c.textAlign='center';c.fillStyle='#9bb58b33';c.fillText('REACTION FIELD — 01',600,45);c.fillText('CONTAINMENT / VALENCE',600,760)}
export class Renderer{
 constructor(canvas){this.canvas=canvas;this.ctx=canvas.getContext('2d');this.shake=0}
 draw(run,time){const c=this.ctx,r=this.canvas.getBoundingClientRect(),d=Math.min(globalThis.devicePixelRatio||1,2);if(this.canvas.width!==Math.round(r.width*d)||this.canvas.height!==Math.round(r.height*d)){this.canvas.width=Math.round(r.width*d);this.canvas.height=Math.round(r.height*d)}c.setTransform(d,0,0,d,0,0);c.fillStyle='#182c24';c.fillRect(0,0,r.width,r.height);let v=camera(r.width,r.height,run.x,run.y);c.save();c.translate(r.width/2,r.height/2);c.scale(v.scale,v.scale);c.translate(-v.x,-v.y);if(this.shake>0){c.translate((Math.random()-.5)*this.shake,(Math.random()-.5)*this.shake);this.shake*=.85;if(this.shake<.5)this.shake=0}chamber(c,time);c.save();c.beginPath();c.rect(ARENA_BOUNDS.left,ARENA_BOUNDS.top,ARENA_BOUNDS.right-ARENA_BOUNDS.left,ARENA_BOUNDS.bottom-ARENA_BOUNDS.top);c.clip();let enemies=run.state==='menu'?[{id:1,x:300,y:240,r:18,type:0},{id:2,x:890,y:550,r:18,type:0},{id:3,x:920,y:170,r:13,type:1},{id:4,x:190,y:610,r:18,type:0}]:run.enemies;for(let h of run.hazards||[])hazard(c,h,time);for(let e of enemies)if(e.type===0)acidAura(c,e,time);for(let drop of run.drops){if(drop.kind==='diamond')diamond(c,drop,time);else if(MATERIALS[drop.material])bottle(c,drop.x,drop.y,drop.material,time)}if(run.state==='menu'){bottle(c,420,500,'water',time);bottle(c,780,300,'hydrogen',time);bottle(c,800,600,'oxygen',time)}let sprites=enemies.map(e=>({y:e.y,draw:()=>enemy(c,e,time)}));sprites.push({y:run.y,draw:()=>player(c,run.x,run.y,run.angle,run.state==='menu'?{type:run.startingGun,level:1}:run.lab.gun,time,run.inv)});sprites.sort((a,b)=>a.y-b.y).forEach(s=>s.draw());for(const b of run.bullets)drawProjectile(c,b,run.elapsed);for(const effect of run.weaponEffects||[])drawProjectile(c,effect,run.elapsed);for(let p of run.particles){c.globalAlpha=Math.min(1,p.life*3);ellipse(c,p.x,p.y,2.5,2.5,p.color)}c.globalAlpha=1;c.font='bold 14px monospace';c.textAlign='center';for(let n of run.texts){c.font=n.kind==='burn'?'bold 12px sans-serif':'bold 14px monospace';c.globalAlpha=Math.min(1,n.life*3);c.fillStyle=n.color;c.strokeStyle='#1a3027';c.lineWidth=3;c.strokeText(n.value,n.x,n.y);c.fillText(n.value,n.x,n.y)}c.globalAlpha=1;c.restore();c.restore();bossBar(c,enemies,r.width)}
}
